/**
 * Calendar's states fixture, with the React fixture's entry names, so a
 * contract's `when <state>` names the same entry in every shell.
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/calendar.ts`. Never edit it by hand.
 */
import * as zag from '@zag-js/date-picker'

import type { ComponentStates } from '@polymorph/solid'

import Calendar from './Calendar'

export const states: ComponentStates = {
  component: 'Calendar',
  entries: [
    {
      name: 'month with selection',
      render: (overrides = {}) => (
        <Calendar
          defaultValue={zag.parse('2026-07-15') as zag.CalendarDate}
          aria-label="Due date"
          {...overrides}
        />
      ),
      expect: { role: 'application' },
    },
    {
      name: 'today visible',
      render: (overrides = {}) => <Calendar aria-label="Due date, this month" {...overrides} />,
      expect: { role: 'application' },
    },
    {
      name: 'min/max bounds',
      render: (overrides = {}) => (
        <Calendar
          defaultValue={zag.parse('2026-07-15') as zag.CalendarDate}
          minValue={zag.parse('2026-07-10') as zag.CalendarDate}
          maxValue={zag.parse('2026-07-20') as zag.CalendarDate}
          aria-label="Due date, within a narrow range"
          {...overrides}
        />
      ),
      expect: { role: 'application' },
    },
    {
      name: 'unavailable dates',
      render: (overrides = {}) => (
        <Calendar
          defaultValue={zag.parse('2026-07-15') as zag.CalendarDate}
          isDateUnavailable={(date: zag.CalendarDate) =>
            [0, 6].includes(date.toDate('UTC').getUTCDay())
          }
          aria-label="Due date, weekdays only"
          {...overrides}
        />
      ),
      expect: { role: 'application' },
    },
    {
      name: 'week start override',
      render: (overrides = {}) => (
        <Calendar
          defaultValue={zag.parse('2026-07-15') as zag.CalendarDate}
          firstDayOfWeek={1}
          aria-label="Due date, weeks from Monday"
          {...overrides}
        />
      ),
      expect: { role: 'application' },
    },
    {
      name: 'another locale',
      render: (overrides = {}) => (
        <Calendar
          defaultValue={zag.parse('2026-07-15') as zag.CalendarDate}
          locale="de-DE"
          aria-label="Fälligkeitsdatum"
          {...overrides}
        />
      ),
      expect: { role: 'application' },
    },
    {
      name: 'disabled',
      render: (overrides = {}) => (
        <Calendar
          disabled={true}
          defaultValue={zag.parse('2026-07-15') as zag.CalendarDate}
          aria-label="Due date, unavailable"
          {...overrides}
        />
      ),
      expect: { role: 'application' },
    },
  ],
}
